-- PROPOSTO. Validacao relacional em SQLite nao prova SQLCipher.
-- Chave SQLCipher fornecida pelo adapter nativo ANTES de qualquer acesso.
PRAGMA foreign_keys = ON;
BEGIN;
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL, checksum TEXT NOT NULL);
CREATE TABLE identities(id TEXT PRIMARY KEY, public_id TEXT NOT NULL UNIQUE, ed_public BLOB NOT NULL CHECK(length(ed_public)=32), x_public BLOB NOT NULL CHECK(length(x_public)=32), key_ref TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL);
CREATE TABLE devices(id TEXT PRIMARY KEY, identity_id TEXT NOT NULL REFERENCES identities(id), signing_public BLOB NOT NULL CHECK(length(signing_public)=32), grant BLOB NOT NULL, added_at INTEGER NOT NULL, revoked_at INTEGER);
CREATE TABLE contacts(id TEXT PRIMARY KEY, ed_public BLOB NOT NULL CHECK(length(ed_public)=32), x_public BLOB NOT NULL CHECK(length(x_public)=32), fingerprint TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, verification TEXT NOT NULL DEFAULT 'unverified' CHECK(verification IN ('unverified','verified','changed','blocked')), verified_at INTEGER);
CREATE TABLE contact_key_history(contact_id TEXT NOT NULL REFERENCES contacts(id) ON DELETE CASCADE, version INTEGER NOT NULL, bundle BLOB NOT NULL, accepted_at INTEGER, PRIMARY KEY(contact_id,version));
CREATE TABLE profiles(identity_id TEXT PRIMARY KEY REFERENCES identities(id), display_name TEXT NOT NULL DEFAULT '', bio TEXT NOT NULL DEFAULT '', avatar_object_id TEXT, visibility TEXT NOT NULL DEFAULT 'contacts' CHECK(visibility IN ('hidden','contacts','public')), revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE cards(id TEXT PRIMARY KEY, identity_id TEXT NOT NULL REFERENCES identities(id), revision INTEGER NOT NULL CHECK(revision>0), public_bundle BLOB NOT NULL, signature BLOB NOT NULL CHECK(length(signature)=64), expires_at INTEGER NOT NULL, UNIQUE(identity_id,revision));
CREATE TABLE conversations(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('direct','group','channel','saved')), owner_identity_id TEXT NOT NULL REFERENCES identities(id), title TEXT NOT NULL, epoch INTEGER NOT NULL DEFAULT 0 CHECK(epoch>=0), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE members(conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, member_key TEXT NOT NULL, device_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','admin','moderator','member','reader')), joined_epoch INTEGER NOT NULL, left_epoch INTEGER, PRIMARY KEY(conversation_id,member_key,device_id));
CREATE TABLE messages(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, author_key TEXT NOT NULL, device_id TEXT NOT NULL, body TEXT, created_at INTEGER NOT NULL, received_at INTEGER, expires_at INTEGER, revision INTEGER NOT NULL DEFAULT 1, delivery_state TEXT NOT NULL CHECK(delivery_state IN ('draft','queued','sending','accepted','received','read','failed','expired','deleted')), reply_to_id TEXT REFERENCES messages(id) ON DELETE SET NULL, deleted_at INTEGER, CHECK(expires_at IS NULL OR expires_at>=created_at));
CREATE INDEX messages_conversation_time ON messages(conversation_id,created_at,id);
CREATE INDEX messages_expiry ON messages(expires_at) WHERE expires_at IS NOT NULL;
CREATE TABLE message_events(id TEXT PRIMARY KEY, message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, actor_key TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('edit','delete','reaction','receipt','forward')), version INTEGER NOT NULL, event_bytes BLOB NOT NULL, created_at INTEGER NOT NULL, UNIQUE(message_id,actor_key,kind,version));
CREATE TABLE reactions(message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, actor_key TEXT NOT NULL, emoji TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), event_version INTEGER NOT NULL, PRIMARY KEY(message_id,actor_key,emoji));
CREATE TABLE objects(id TEXT PRIMARY KEY, sha256 BLOB NOT NULL CHECK(length(sha256)=32), mime_type TEXT NOT NULL, byte_size INTEGER NOT NULL CHECK(byte_size>=0 AND byte_size<=52428800), key_ref TEXT NOT NULL, encrypted_path TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, expires_at INTEGER);
CREATE TABLE object_chunks(object_id TEXT NOT NULL REFERENCES objects(id) ON DELETE CASCADE, chunk_no INTEGER NOT NULL CHECK(chunk_no>=0), ciphertext_hash BLOB NOT NULL CHECK(length(ciphertext_hash)=32), cipher_size INTEGER NOT NULL CHECK(cipher_size>0 AND cipher_size<=262184), encrypted_path TEXT NOT NULL UNIQUE, PRIMARY KEY(object_id,chunk_no));
CREATE TABLE attachments(message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, object_id TEXT NOT NULL REFERENCES objects(id), file_name TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), PRIMARY KEY(message_id,object_id), UNIQUE(message_id,ordinal));
CREATE TABLE folders(id TEXT PRIMARY KEY, name TEXT NOT NULL, sort_order INTEGER NOT NULL, color INTEGER, icon TEXT);
CREATE TABLE folder_conversations(folder_id TEXT NOT NULL REFERENCES folders(id) ON DELETE CASCADE, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sort_order INTEGER NOT NULL, PRIMARY KEY(folder_id,conversation_id));
CREATE TABLE preferences(key TEXT PRIMARY KEY, value_json TEXT NOT NULL CHECK(json_valid(value_json)), revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE key_material(id TEXT PRIMARY KEY, purpose TEXT NOT NULL, wrapped_bytes BLOB NOT NULL, wrapping_key_ref TEXT NOT NULL, format_version INTEGER NOT NULL CHECK(format_version>0), created_at INTEGER NOT NULL, retired_at INTEGER);
CREATE TABLE prekeys(id TEXT PRIMARY KEY, identity_id TEXT NOT NULL REFERENCES identities(id), device_id TEXT NOT NULL REFERENCES devices(id), kind TEXT NOT NULL CHECK(kind IN ('signed','one_time')), public_bytes BLOB NOT NULL CHECK(length(public_bytes)=32), key_ref TEXT NOT NULL REFERENCES key_material(id), signature BLOB, expires_at INTEGER NOT NULL, consumed_at INTEGER);
CREATE TABLE sessions(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, local_device_id TEXT NOT NULL REFERENCES devices(id), peer_device_id TEXT NOT NULL, state_blob BLOB NOT NULL, format_version INTEGER NOT NULL, revision INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL, UNIQUE(conversation_id,local_device_id,peer_device_id));
CREATE TABLE skipped_keys(session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, ratchet_public BLOB NOT NULL CHECK(length(ratchet_public)=32), message_no INTEGER NOT NULL CHECK(message_no>=0), wrapped_key BLOB NOT NULL, expires_at INTEGER NOT NULL, PRIMARY KEY(session_id,ratchet_public,message_no));
CREATE TABLE outbox(id TEXT PRIMARY KEY, message_id TEXT REFERENCES messages(id) ON DELETE CASCADE, session_id TEXT REFERENCES sessions(id), destination_mailbox TEXT NOT NULL, ciphertext BLOB NOT NULL CHECK(length(ciphertext)<=1048576), payload_hash BLOB NOT NULL CHECK(length(payload_hash)=32), transport_state TEXT NOT NULL CHECK(transport_state IN ('queued','leased','accepted','failed','expired')), attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts>=0), next_attempt_at INTEGER NOT NULL, lease_until INTEGER, expires_at INTEGER NOT NULL, relay_envelope_id TEXT, UNIQUE(id,destination_mailbox));
CREATE INDEX outbox_ready ON outbox(transport_state,next_attempt_at);
CREATE TABLE inbox_dedup(mailbox_id TEXT NOT NULL, delivery_id TEXT NOT NULL, payload_hash BLOB NOT NULL CHECK(length(payload_hash)=32), committed_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, PRIMARY KEY(mailbox_id,delivery_id));
CREATE TABLE replay_nonces(issuer_key TEXT NOT NULL, record_type TEXT NOT NULL, nonce BLOB NOT NULL, expires_at INTEGER NOT NULL, PRIMARY KEY(issuer_key,record_type,nonce));
CREATE TABLE sync_state(scope TEXT PRIMARY KEY, cursor TEXT, revision INTEGER NOT NULL DEFAULT 0, last_success_at INTEGER, last_error_code TEXT);
CREATE TABLE media_items(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('film','series','anime','manga','book','music','episode','volume','chapter','album','track','repository')), title TEXT NOT NULL, parent_id TEXT REFERENCES media_items(id), metadata_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata_json)), source TEXT, source_id TEXT, updated_at INTEGER NOT NULL, UNIQUE(source,source_id));
CREATE TABLE library_entries(identity_id TEXT NOT NULL REFERENCES identities(id), media_id TEXT NOT NULL REFERENCES media_items(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'saved', progress_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(progress_json)), rating INTEGER CHECK(rating BETWEEN 0 AND 100), public_in_card INTEGER NOT NULL DEFAULT 0 CHECK(public_in_card IN (0,1)), saved_at INTEGER NOT NULL, PRIMARY KEY(identity_id,media_id));
CREATE TABLE catalog_snapshots(id TEXT PRIMARY KEY, source_url TEXT NOT NULL, source_revision TEXT, fetched_at INTEGER NOT NULL, source_hash BLOB NOT NULL CHECK(length(source_hash)=32), etag TEXT, item_count INTEGER NOT NULL CHECK(item_count>=0));
CREATE TABLE repositories(id TEXT PRIMARY KEY, full_name TEXT NOT NULL UNIQUE, url TEXT NOT NULL, language TEXT, license_spdx TEXT, stars INTEGER CHECK(stars>=0), forks INTEGER CHECK(forks>=0), stars_week INTEGER, category TEXT, topics_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(topics_json)), snapshot_id TEXT NOT NULL REFERENCES catalog_snapshots(id), media_id TEXT REFERENCES media_items(id));
CREATE TABLE archive_personas(id TEXT PRIMARY KEY, public_key BLOB NOT NULL UNIQUE CHECK(length(public_key)=32), key_ref TEXT NOT NULL REFERENCES key_material(id));
CREATE TABLE archive_objects(hash TEXT PRIMARY KEY CHECK(length(hash)=64), kind TEXT NOT NULL CHECK(kind IN ('article','refutation')), canonical_bytes BLOB NOT NULL, author_public BLOB NOT NULL CHECK(length(author_public)=32), signature BLOB NOT NULL CHECK(length(signature)=64), supersedes_hash TEXT REFERENCES archive_objects(hash), visibility TEXT NOT NULL CHECK(visibility IN ('public','restricted')), created_at INTEGER NOT NULL);
CREATE TABLE archive_claims(object_hash TEXT NOT NULL REFERENCES archive_objects(hash) ON DELETE CASCADE, claim_id TEXT NOT NULL, text TEXT NOT NULL, PRIMARY KEY(object_hash,claim_id));
CREATE TABLE archive_refutations(refutation_hash TEXT PRIMARY KEY REFERENCES archive_objects(hash) ON DELETE CASCADE, target_hash TEXT NOT NULL, target_claim_id TEXT NOT NULL, FOREIGN KEY(target_hash,target_claim_id) REFERENCES archive_claims(object_hash,claim_id));
CREATE TABLE archive_replicas(object_hash TEXT NOT NULL REFERENCES archive_objects(hash) ON DELETE CASCADE, replica_id TEXT NOT NULL, endpoint TEXT NOT NULL, last_verified_at INTEGER, promised_until INTEGER, PRIMARY KEY(object_hash,replica_id));
CREATE VIRTUAL TABLE message_search USING fts5(message_id UNINDEXED, conversation_id UNINDEXED, body, tokenize='unicode61');
CREATE TRIGGER message_search_insert AFTER INSERT ON messages WHEN new.body IS NOT NULL BEGIN INSERT INTO message_search(message_id,conversation_id,body) VALUES(new.id,new.conversation_id,new.body); END;
CREATE TRIGGER message_search_update AFTER UPDATE OF body ON messages BEGIN DELETE FROM message_search WHERE message_id=old.id; INSERT INTO message_search(message_id,conversation_id,body) SELECT new.id,new.conversation_id,new.body WHERE new.body IS NOT NULL; END;
CREATE TRIGGER message_search_delete AFTER DELETE ON messages BEGIN DELETE FROM message_search WHERE message_id=old.id; END;
CREATE VIRTUAL TABLE media_search USING fts5(media_id UNINDEXED,title, tokenize='unicode61');
CREATE TRIGGER media_search_insert AFTER INSERT ON media_items BEGIN INSERT INTO media_search(media_id,title) VALUES(new.id,new.title); END;
CREATE TRIGGER media_search_update AFTER UPDATE OF title ON media_items BEGIN DELETE FROM media_search WHERE media_id=old.id; INSERT INTO media_search(media_id,title) VALUES(new.id,new.title); END;
CREATE TRIGGER media_search_delete AFTER DELETE ON media_items BEGIN DELETE FROM media_search WHERE media_id=old.id; END;
PRAGMA user_version = 1;
COMMIT;
